window.LOT_STATUES={"id": "l20261119a", "label": "Statues : Just Someone pull day (19 nov)", "accounts": [{"id": "atlas", "handle": "@just.someone.nox · pull day", "caption": "pas besoin de 10 exercices pour ton pull day, juste des bons. 6 muscles, 1 exo à choisir par slide : largeur du dos, épaisseur, bas du dos, trapèzes, arrière d'épaule et biceps. tu prends celui que tu peux faire avec la meilleure technique, pas celui qui flatte l'ego. 3 séries par exo, 2 minutes de repos sur les gros mouvements, 1 minute 30 sur le reste, et tu t'arrêtes à 1 ou 2 reps de l'échec. capture la slide « ta séance » et coche au fur et à mesure. enregistre pour ton prochain pull day et dis en commentaire : tractions ou pullover ? 👇\n\n#musculation #pullday #dos #gymtips #seancedesport", "slides": ["l20261119a-atlas-slide-01.jpg", "l20261119a-atlas-slide-02.jpg", "l20261119a-atlas-slide-03.jpg", "l20261119a-atlas-slide-04.jpg", "l20261119a-atlas-slide-05.jpg", "l20261119a-atlas-slide-06.jpg", "l20261119a-atlas-slide-07.jpg", "l20261119a-atlas-slide-08.jpg", "l20261119a-atlas-slide-09.jpg"]}]};window.PHONES_STATUES=[["Just Someone (FR)",["atlas"]]];
